export type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, Set<EventCallback>> = new Map();

  publish(event: string, payload: any): void {
    const subs = this.subscribers.get(event);
    if (!subs) return;
    for (const cb of subs) {
      try {
        cb(payload);
      } catch (err) {
        // swallow subscriber errors to avoid breaking other subscribers
        // In a real system we would log this
      }
    }
  }

  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, new Set());
    }
    this.subscribers.get(event)!.add(callback);
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();

  create(data: { name: string; email: string }): User {
    const user: User = { id: randomUUID(), name: data.name, email: data.email };
    this.users.set(user.id, user);
    return user;
  }

  getById(id: string): User | undefined {
    return this.users.get(id);
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, data: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.users.get(id);
    if (!existing) return undefined;
    const updated: User = { ...existing, ...data };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description?: string;
  memberIds: string[];
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  create(data: { name: string; description?: string; memberIds?: string[] }): Project {
    const project: Project = {
      id: randomUUID(),
      name: data.name,
      description: data.description,
      memberIds: data.memberIds ? [...data.memberIds] : [],
    };
    this.projects.set(project.id, project);
    return project;
  }

  getById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, data: Partial<Omit<Project, 'id'>>): Project | undefined {
    const existing = this.projects.get(id);
    if (!existing) return undefined;
    const updated: Project = { ...existing, ...data };
    if (data.memberIds) updated.memberIds = [...data.memberIds];
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    return project;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assigneeId?: string;
  projectId: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();

  constructor(private bus: EventBus) {}

  create(data: { title: string; description?: string; projectId: string }): Task {
    const task: Task = {
      id: randomUUID(),
      title: data.title,
      description: data.description,
      status: 'todo',
      projectId: data.projectId,
    };
    this.tasks.set(task.id, task);
    return task;
  }

  getById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  getAll(): Task[] {
    return Array.from(this.tasks.values());
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, data: Partial<Omit<Task, 'id'>>): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...data };
    this.tasks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.tasks.delete(id);
  }

  assign(id: string, assigneeId: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assigneeId = assigneeId;
    this.bus.publish('task.assigned', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: assigneeId,
    });
    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;

    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const oldIndex = order.indexOf(task.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) return undefined;
    if (newIndex < oldIndex) return undefined; // forward-only
    if (newIndex === oldIndex) return task; // no change

    const oldStatus = task.status;
    task.status = newStatus;
    this.bus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });
    return task;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: number; // epoch ms
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private bus: EventBus, private getTaskTitle: (taskId: string) => string | undefined, private getUserName: (userId: string) => string | undefined) {}

  create(data: { taskId: string; authorId: string; body: string }): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId: data.taskId,
      authorId: data.authorId,
      body: data.body,
      createdAt: Date.now(),
    };
    this.comments.set(comment.id, comment);

    const taskTitle = this.getTaskTitle(comment.taskId);
    const authorName = this.getUserName(comment.authorId);

    this.bus.publish('comment.added', {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle,
      authorId: comment.authorId,
      authorName,
    });

    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter((c) => c.taskId === taskId);
  }

  getById(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  delete(id: string): boolean {
    return this.comments.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(
    private bus: EventBus,
    private getTaskAssignee: (taskId: string) => string | undefined,
  ) {
    this.subscribeToEvents();
  }

  private subscribeToEvents() {
    this.bus.subscribe('task.assigned', (payload: any) => {
      const { taskId, taskTitle, assigneeId } = payload || {};
      if (!assigneeId) return;
      const message = `Task assigned: "${taskTitle || taskId}" assigned to you.`;
      this.createNotification(assigneeId, message);
    });

    this.bus.subscribe('task.statusChanged', (payload: any) => {
      const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload || {};
      if (!assigneeId) return;
      const message = `Task status changed: "${taskTitle || taskId}" ${oldStatus} -> ${newStatus}.`;
      this.createNotification(assigneeId, message);
    });

    this.bus.subscribe('comment.added', (payload: any) => {
      const { taskId, taskTitle, authorId, authorName } = payload || {};
      const assigneeId = this.getTaskAssignee(taskId);
      if (!assigneeId) return;
      const message = `New comment on "${taskTitle || taskId}" from ${authorName || authorId}.`;
      this.createNotification(assigneeId, message);
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notif: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: Date.now(),
    };
    this.notifications.set(notif.id, notif);
    return notif;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter((n) => n.userId === userId);
  }

  markAsRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    return n;
  }
}

import http, { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, TaskStatus } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

async function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return resolve(undefined);
      try {
        resolve(JSON.parse(raw));
      } catch (err) {
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', (err) => reject(err));
  });
}

function send(res: ServerResponse, status: number, data?: any) {
  const payload = data === undefined ? '' : JSON.stringify(data);
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json');
  res.end(payload);
}

export function createApiServer(
  userSvc: UserService,
  projectSvc: ProjectService,
  taskSvc: TaskService,
  commentSvc: CommentService,
  notifSvc: NotificationService,
): http.Server {
  const server = http.createServer(async (req, res) => {
    if (!req.url || !req.method) return send(res, 404, { error: 'Not found' });

    // CORS for convenience in demos
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
    if (req.method === 'OPTIONS') return send(res, 200, {});

    const url = new URL(req.url, 'http://localhost');
    const pathname = url.pathname;
    const parts = pathname.split('/').filter(Boolean);
    const method = req.method.toUpperCase();

    try {
      // Users
      if (method === 'GET' && pathname === '/users') {
        return send(res, 200, userSvc.getAll());
      }
      if (method === 'POST' && pathname === '/users') {
        const body = await parseBody(req);
        if (!body || !body.name || !body.email) return send(res, 400, { error: 'name and email required' });
        const user = userSvc.create({ name: body.name, email: body.email });
        return send(res, 201, user);
      }
      if (parts[0] === 'users' && parts.length === 2) {
        const id = parts[1];
        if (method === 'GET') {
          const user = userSvc.getById(id);
          return user ? send(res, 200, user) : send(res, 404, { error: 'User not found' });
        }
        if (method === 'PUT') {
          const body = await parseBody(req);
          const updated = userSvc.update(id, { name: body?.name, email: body?.email });
          return updated ? send(res, 200, updated) : send(res, 404, { error: 'User not found' });
        }
        if (method === 'DELETE') {
          const ok = userSvc.delete(id);
          return ok ? send(res, 204) : send(res, 404, { error: 'User not found' });
        }
      }

      // Projects
      if (method === 'GET' && pathname === '/projects') {
        return send(res, 200, projectSvc.getAll());
      }
      if (method === 'POST' && pathname === '/projects') {
        const body = await parseBody(req);
        if (!body || !body.name) return send(res, 400, { error: 'name required' });
        const project = projectSvc.create({ name: body.name, description: body.description, memberIds: body.memberIds });
        return send(res, 201, project);
      }
      if (parts[0] === 'projects' && parts.length === 2) {
        const id = parts[1];
        if (method === 'GET') {
          const p = projectSvc.getById(id);
          return p ? send(res, 200, p) : send(res, 404, { error: 'Project not found' });
        }
        if (method === 'PUT') {
          const body = await parseBody(req);
          const updated = projectSvc.update(id, {
            name: body?.name,
            description: body?.description,
            memberIds: body?.memberIds,
          });
          return updated ? send(res, 200, updated) : send(res, 404, { error: 'Project not found' });
        }
        if (method === 'DELETE') {
          const ok = projectSvc.delete(id);
          return ok ? send(res, 204) : send(res, 404, { error: 'Project not found' });
        }
      }
      if (parts[0] === 'projects' && parts.length === 3 && parts[2] === 'members') {
        const id = parts[1];
        const body = await parseBody(req);
        if (!body || !body.userId) return send(res, 400, { error: 'userId required' });
        if (method === 'POST') {
          const p = projectSvc.addMember(id, body.userId);
          return p ? send(res, 200, p) : send(res, 404, { error: 'Project not found' });
        }
        if (method === 'DELETE') {
          const p = projectSvc.removeMember(id, body.userId);
          return p ? send(res, 200, p) : send(res, 404, { error: 'Project not found' });
        }
      }

      // Tasks
      if (method === 'GET' && parts[0] === 'tasks' && parts.length === 1) {
        const projectId = url.searchParams.get('projectId');
        if (!projectId) return send(res, 400, { error: 'projectId query required' });
        return send(res, 200, taskSvc.getByProject(projectId));
      }
      if (method === 'POST' && pathname === '/tasks') {
        const body = await parseBody(req);
        if (!body || !body.title || !body.projectId) return send(res, 400, { error: 'title and projectId required' });
        const t = taskSvc.create({ title: body.title, description: body.description, projectId: body.projectId });
        return send(res, 201, t);
      }
      if (parts[0] === 'tasks' && parts.length === 2) {
        const id = parts[1];
        if (method === 'GET') {
          const t = taskSvc.getById(id);
          return t ? send(res, 200, t) : send(res, 404, { error: 'Task not found' });
        }
        if (method === 'PUT') {
          const body = await parseBody(req);
          // Allow updating title/description only via generic update
          const t = taskSvc.update(id, { title: body?.title, description: body?.description });
          return t ? send(res, 200, t) : send(res, 404, { error: 'Task not found' });
        }
        if (method === 'DELETE') {
          const ok = taskSvc.delete(id);
          return ok ? send(res, 204) : send(res, 404, { error: 'Task not found' });
        }
      }
      if (parts[0] === 'tasks' && parts.length === 3 && parts[2] === 'assign' && method === 'PUT') {
        const id = parts[1];
        const body = await parseBody(req);
        if (!body || !body.assigneeId) return send(res, 400, { error: 'assigneeId required' });
        const t = taskSvc.assign(id, body.assigneeId);
        return t ? send(res, 200, t) : send(res, 404, { error: 'Task not found' });
      }
      if (parts[0] === 'tasks' && parts.length === 3 && parts[2] === 'status' && method === 'PUT') {
        const id = parts[1];
        const body = await parseBody(req);
        const status = body?.status as TaskStatus | undefined;
        if (!status) return send(res, 400, { error: 'status required' });
        const t = taskSvc.changeStatus(id, status);
        return t ? send(res, 200, t) : send(res, 404, { error: 'Task not found or invalid status transition' });
      }

      // Comments
      if (method === 'GET' && parts[0] === 'comments' && parts.length === 1) {
        const taskId = url.searchParams.get('taskId');
        if (!taskId) return send(res, 400, { error: 'taskId query required' });
        return send(res, 200, commentSvc.getByTask(taskId));
      }
      if (method === 'POST' && pathname === '/comments') {
        const body = await parseBody(req);
        if (!body || !body.taskId || !body.authorId || !body.body) return send(res, 400, { error: 'taskId, authorId, body required' });
        const c = commentSvc.create({ taskId: body.taskId, authorId: body.authorId, body: body.body });
        return send(res, 201, c);
      }
      if (parts[0] === 'comments' && parts.length === 2) {
        const id = parts[1];
        if (method === 'GET') {
          const c = commentSvc.getById(id);
          return c ? send(res, 200, c) : send(res, 404, { error: 'Comment not found' });
        }
        if (method === 'DELETE') {
          const ok = commentSvc.delete(id);
          return ok ? send(res, 204) : send(res, 404, { error: 'Comment not found' });
        }
      }

      // Notifications
      if (method === 'GET' && parts[0] === 'notifications' && parts.length === 1) {
        const userId = url.searchParams.get('userId');
        if (!userId) return send(res, 400, { error: 'userId query required' });
        return send(res, 200, notifSvc.getByUser(userId));
      }
      if (method === 'PUT' && parts[0] === 'notifications' && parts.length === 3 && parts[2] === 'read') {
        const id = parts[1];
        const n = notifSvc.markAsRead(id);
        return n ? send(res, 200, n) : send(res, 404, { error: 'Notification not found' });
      }

      return send(res, 404, { error: 'Not found' });
    } catch (err: any) {
      return send(res, 400, { error: err?.message || 'Bad request' });
    }
  });

  return server;
}

import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { createApiServer } from './router';

const bus = new EventBus();

const userSvc = new UserService();
const projectSvc = new ProjectService();
